using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Talent;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class RecruitmentOfferTests
{
 class Time:TimeProvider{public DateTimeOffset Now=new(2026,11,24,18,0,0,TimeSpan.Zero);public override DateTimeOffset GetUtcNow()=>Now;}
 class User(int id=1,bool hr=true):ICurrentUser{public string Email=>$"offer{id}@example.local";public int? EmployeeId=>id;public int UserId=>id;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>hr;public bool Can(string p)=>hr;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static RecruitmentOffers S(AppDbContext d,int id=1,bool hr=true,Time? t=null){var u=new User(id,hr);var c=new AppClock(t??new Time());return new(d,u,c,new AuditService(d,u,c));}
 static async Task<int> CandidateId(AppDbContext d)=>await d.Set<Candidate>().Where(x=>x.Stage==CandidateStage.Offer).Select(x=>x.Id).FirstAsync();
 static Task Propose(AppDbContext d,int candidate)=>S(d).ProposeAsync(candidate,"Demo role",25000,"EGP",new(2027,1,1),new(2026,12,15),"Fictional internal terms, not a contract");
 [Fact]public async Task IndependentApprovalThenEvidenceAcceptanceDoesNotCreateEmployment(){await using var d=await Db();var id=await CandidateId(d);var before=await d.Set<Employee>().CountAsync();await Propose(d,id);var offer=Assert.Single((await S(d).GetAsync()).Offers);await Assert.ThrowsAsync<DomainException>(()=>S(d).DecideAsync(offer.Id,"Approved","Self"));await S(d,2).DecideAsync(offer.Id,"Approved","Reviewed proposal");await S(d).DecideAsync(offer.Id,"Accepted","Fictional candidate acceptance evidence REF-1");Assert.Equal(before,await d.Set<Employee>().CountAsync());Assert.Equal(CandidateStage.Offer,(await d.Set<Candidate>().FindAsync(id))!.Stage);Assert.Equal(2,(await S(d).GetAsync()).Events.Count);await Assert.ThrowsAsync<DomainException>(()=>S(d).DecideAsync(offer.Id,"Withdrawn","Cannot rewrite accepted history"));}
 [Fact]public async Task ProposalsAndDecisionsAreAppendOnly(){await using var d=await Db();var id=await CandidateId(d);await Propose(d,id);var offer=await d.Set<CandidateOffer>().FirstAsync();offer.MonthlyBase=1;await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());d.ChangeTracker.Clear();await S(d,2).DecideAsync(offer.Id,"Rejected","Not appropriate");var ev=await d.Set<CandidateOfferEvent>().FirstAsync();ev.Note="Overwrite";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task OneActiveProposalAndValidStateTransitionsRequired(){await using var d=await Db();var id=await CandidateId(d);await Propose(d,id);var offer=await d.Set<CandidateOffer>().FirstAsync();await Assert.ThrowsAsync<DomainException>(()=>Propose(d,id));await Assert.ThrowsAsync<DomainException>(()=>S(d).DecideAsync(offer.Id,"Accepted","Unapproved"));await S(d,2).DecideAsync(offer.Id,"Rejected","Not suitable");await Propose(d,id);Assert.Equal(2,await d.Set<CandidateOffer>().CountAsync());}
 [Fact]public async Task ExpiryAndPermissionsAndTermsAreChecked(){await using var d=await Db();var id=await CandidateId(d);await Assert.ThrowsAsync<DomainException>(()=>S(d,6,false).GetAsync());await Assert.ThrowsAsync<DomainException>(()=>S(d).ProposeAsync(id,"Demo",-1,"EGP",new(2027,1,1),new(2026,12,1),"Terms"));await Propose(d,id);var offer=await d.Set<CandidateOffer>().FirstAsync();var t=new Time{Now=new(2026,12,16,10,0,0,TimeSpan.Zero)};await Assert.ThrowsAsync<DomainException>(()=>S(d,2,t:t).DecideAsync(offer.Id,"Approved","Expired"));}
 [Fact]public async Task HiringStageNeedsLatestAcceptedOfferButDoesNotCreateEmployee(){await using var d=await Db();var id=await CandidateId(d);var u=new User();var c=new AppClock(new Time());var talent=new TalentService(d,u,new AccessScope(d,u),c,new AuditService(d,u,c),new NotificationService(d,u,c));await Assert.ThrowsAsync<DomainException>(()=>talent.MoveCandidateAsync(id,false));await Propose(d,id);var offer=await d.Set<CandidateOffer>().FirstAsync();await S(d,2).DecideAsync(offer.Id,"Approved","Reviewed");await S(d).DecideAsync(offer.Id,"Accepted","Recorded fictional candidate decision");var count=await d.Set<Employee>().CountAsync();await talent.MoveCandidateAsync(id,false);Assert.Equal(CandidateStage.Hired,(await d.Set<Candidate>().FindAsync(id))!.Stage);Assert.Equal(count,await d.Set<Employee>().CountAsync());}
 [Fact]public async Task CandidateRejectionWithdrawsActiveProposal(){await using var d=await Db();var id=await CandidateId(d);await Propose(d,id);var u=new User();var c=new AppClock(new Time());var talent=new TalentService(d,u,new AccessScope(d,u),c,new AuditService(d,u,c),new NotificationService(d,u,c));await talent.MoveCandidateAsync(id,true);Assert.Equal("Withdrawn",(await d.Set<CandidateOfferEvent>().SingleAsync()).Kind);Assert.Equal(CandidateStage.Rejected,(await d.Set<Candidate>().FindAsync(id))!.Stage);}
}
